"""The kubernetes provider's CRD extension, generated by the pinned `pulumi` from the plugin the lock registers.

The provider's CRD extension (kluster-ops#160) is an SDK `pulumi package
gen-sdk` generates from a CRD manifest and the kubernetes plugin. The module
generates one, for one throwaway CRD, with the CLI `mise.toml` pins and a
`PULUMI_HOME` of the module's own, and its cases hold two things about that
run:

-   the plugin it fetches and generates with is the version the locked
    `pulumi-kubernetes` registers, the only plugin in the home, and the one
    the generated SDK registers;
-   what `gen-sdk` leaves behind lands in the module's own temporary
    directory, not in the one the module would otherwise have used.

Every command leads a POSIX session of its own that ends with it
(`process_sessions`), so a `pulumi` stopped at its bound takes its plugins
with it.

This suite fetches, an exception to the engine suites' fetching nothing
(testing.md §8): `pulumi package gen-sdk` needs the kubernetes plugin, at the version the
locked `pulumi-kubernetes` registers. It is downloaded once per worker that
runs one of the module's cases, because each worker process builds the
module's fixture, and the home it downloads into, for itself. Each download is
that version's release asset: the schema source names the version, so nothing
asks GitHub's API for the latest release.
"""

from __future__ import annotations

import json
import os
import shutil
import subprocess as sp
from collections.abc import Iterator, Mapping
from dataclasses import dataclass
from importlib.metadata import version
from pathlib import Path
from typing import Any, cast

import process_sessions
import pytest
from scratch_projects import LEFT_BEHIND, cli_directories

pytestmark = pytest.mark.skipif(
    shutil.which('pulumi') is None or shutil.which('uv') is None, reason='the pinned pulumi CLI or uv is not on PATH'
)

#: One CRD with one served version and one field: the smallest manifest the
#: extension generates a resource class from.
CRD = """\
apiVersion: apiextensions.k8s.io/v1
kind: CustomResourceDefinition
metadata:
  name: widgets.probe.example.com
spec:
  group: probe.example.com
  names: {kind: Widget, listKind: WidgetList, plural: widgets, singular: widget}
  scope: Namespaced
  versions:
    - name: v1
      served: true
      storage: true
      schema:
        openAPIV3Schema:
          type: object
          properties:
            spec:
              type: object
              properties:
                size: {type: integer}
"""

#: How long one case may take, the module's plugin download and SDK
#: generation included for the first case a worker runs: set from measured
#: durations rather than from the suite's per-case bound (testing.md §8). On a
#: four-core machine the first case took 6 s idle and 15 s with four times as
#: many busy processes as cores. Twice
#: `COMMAND_TIMEOUT`, so a stalled command fails naming itself before this
#: fires; a stop-loss, which nothing asserts on.
CASE_TIMEOUT = 240

#: How long one `pulumi` command may take before the case fails naming it: a
#: stop-loss, eight times the slowest case measured under that load, and below
#: `CASE_TIMEOUT`.
COMMAND_TIMEOUT = 120

#: The kubernetes plugin the extension is generated with: the one the locked
#: `pulumi-kubernetes` registers. `gen-sdk` is handed it
#: as `kubernetes@<version>`, the one spelling of a plugin name it resolves by
#: version: a bare `kubernetes` installs whatever GitHub's API calls the latest
#: release, a lookup rate-limited per address when no token rides it, and
#: `--version` only relabels the package generated from that plugin.
PLUGIN = version('pulumi-kubernetes')


def _scrubbed(environ: Mapping[str, str]) -> dict[str, str]:
    """The test run's environment, without anything that could steer `pulumi` at another backend."""
    return {key: value for key, value in environ.items() if not key.startswith(('PULUMI_', 'PG', 'KUBE'))}


def _pulumi(*args: str, cwd: Path, env: Mapping[str, str]) -> sp.CompletedProcess[str]:
    """One `pulumi` command, its plugins in its POSIX session and gone with it however it ends."""
    return process_sessions.run(
        ['pulumi', '--non-interactive', *args], cwd=cwd, env=env, text=True, timeout=COMMAND_TIMEOUT
    )


@dataclass
class Extension:
    """The generated extension SDK, the home holding the plugin it was generated with, and where its temporary files went.

    `outer` is the `TMPDIR` the module's commands would have had without
    their own: a directory nothing writes to unless the CLI's temporary files
    escape the module's `temporary`.
    """

    sdk: Path
    home: Path
    temporary: Path
    outer: Path


@pytest.fixture(scope='module')
def extension(tmp_path_factory: pytest.TempPathFactory) -> Iterator[Extension]:
    root = tmp_path_factory.mktemp('extension')
    manifest = root / 'crd.yaml'
    _ = manifest.write_text(CRD)
    outer = root / 'outer'
    outer.mkdir()
    directories = cli_directories(root)
    # A backend of the module's own: with none, and a coding agent's variable in
    # the environment, the pinned CLI signs up an ephemeral Pulumi Cloud account
    # (`currentOrSignupAgentAccount`, pkg/backend/httpstate/backend.go), an
    # outward write no test may make.
    env = (
        _scrubbed(os.environ)
        | {'TMPDIR': str(outer)}
        | directories
        | {
            'PULUMI_BACKEND_URL': f'file://{root / "state"}',
            'PULUMI_SKIP_UPDATE_CHECK': 'true',
        }
    )
    (root / 'state').mkdir()
    source = f'kubernetes@{PLUGIN}'
    generated = _pulumi(
        'package',
        'gen-sdk',
        source,
        '--extension',
        f'name=crds crd-manifest={manifest}',
        '--language',
        'python',
        '--out',
        str(root / 'sdk'),
        cwd=root,
        env=env,
    )
    assert generated.returncode == 0, (
        f'`pulumi package gen-sdk {source}` failed, fetching the plugin or generating the extension from it:\n'
        + generated.stdout
        + generated.stderr
    )
    yield Extension(
        sdk=root / 'sdk' / 'python',
        home=Path(directories['PULUMI_HOME']),
        temporary=Path(env['TMPDIR']),
        outer=outer,
    )
    # The plugin is hundreds of megabytes unpacked: gone with the module, not
    # left for the temporary directory's retention.
    shutil.rmtree(root, ignore_errors=True)


@pytest.mark.timeout(CASE_TIMEOUT)
def test_the_extension_is_generated_by_the_plugin_the_lock_registers(extension: Extension, tmp_path: Path) -> None:
    env = (
        _scrubbed(os.environ)
        | cli_directories(tmp_path, home=extension.home)
        | {
            'PULUMI_BACKEND_URL': f'file://{tmp_path}',
            'PULUMI_SKIP_UPDATE_CHECK': 'true',
        }
    )
    listed = _pulumi('plugin', 'ls', '--json', cwd=tmp_path, env=env)
    assert listed.returncode == 0, listed.stderr
    plugins = cast('list[dict[str, Any]]', json.loads(listed.stdout))
    assert [(plugin['kind'], plugin['name'], plugin['version']) for plugin in plugins] == [
        ('resource', 'kubernetes', PLUGIN)
    ]
    registered = json.loads((extension.sdk / 'pulumi_crds' / 'pulumi-plugin.json').read_text())
    assert (registered['name'], registered['version']) == ('kubernetes', PLUGIN)


@pytest.mark.timeout(CASE_TIMEOUT)
def test_what_the_gen_sdk_leaves_behind_is_in_the_modules_own_temporary_directory(extension: Extension) -> None:
    # `gen-sdk` keeps the plugin's tarball after it unpacks it. With `TMPDIR`
    # its own, that file is the module's, removed with it; without, it lands
    # in the directory the module would otherwise have used.
    escaped = sorted(path.name for path in extension.outer.iterdir() if path.name.startswith(LEFT_BEHIND))
    kept = sorted(path.name for path in extension.temporary.iterdir() if path.name.startswith(LEFT_BEHIND))

    assert escaped == []
    # Not vacuous: the gen-sdk left something, and it is in the module's own.
    assert [name for name in kept if name.startswith('pulumi-plugin-tar')], kept
